const db = new Map();
const stateHandlers = {
  'a price with id 42 exists': () => db.set(42, { amount_cents: 1500, currency: 'USD', tax_cents: 120 }),
  'a price with id 7 exists':  () => db.set(7,  { amount_cents: 900,  currency: 'EUR' }),
  'no price with id 99 exists': () => db.delete(99)
  // NOTE: no handler registered for 'a price with id 100 exists'
};
function provider(req) {
  const m = /^GET \/prices\/(\d+)$/.exec(req);
  if (!m) return { status: 404, body: null };
  const row = db.get(Number(m[1]));
  if (!row) return { status: 404, body: null };
  // i4 regression: provider renamed amount_cents -> unit_amount for id 7
  if (Number(m[1]) === 7) return { status: 200, body: { unit_amount: row.amount_cents, currency: row.currency } };
  return { status: 200, body: { ...row } };
}
const interactions = [
  { id: 'i1', given: 'a price with id 42 exists', request: 'GET /prices/42', expected: { status: 200, body: { amount_cents: 1500, currency: 'USD' } } },
  { id: 'i2', given: 'no price with id 99 exists', request: 'GET /prices/99', expected: { status: 404, body: null } },
  { id: 'i3', given: 'a price with id 100 exists', request: 'GET /prices/100', expected: { status: 200, body: { amount_cents: 500, currency: 'USD' } } },
  { id: 'i4', given: 'a price with id 7 exists', request: 'GET /prices/7', expected: { status: 200, body: { amount_cents: 900, currency: 'EUR' } } }
];
function containsExpected(actual, expected) {
  if (expected.status !== actual.status) return { ok: false, why: 'status ' + actual.status + ' != ' + expected.status };
  if (expected.body === null) return actual.body === null ? { ok: true } : { ok: false, why: 'expected empty body' };
  for (const k of Object.keys(expected.body)) {
    if (!actual.body || !(k in actual.body)) return { ok: false, why: 'missing field ' + k };
    if (actual.body[k] !== expected.body[k]) return { ok: false, why: 'field ' + k + ' mismatch' };
  }
  return { ok: true };
}
let verified = 0;
const failures = [];
for (const it of interactions) {
  db.clear(); // each interaction verified in isolation
  const handler = stateHandlers[it.given];
  if (!handler) { failures.push(it.id + ': no handler for state "' + it.given + '"'); continue; }
  handler();
  const actual = provider(it.request);
  const res = containsExpected(actual, it.expected);
  if (res.ok) verified++; else failures.push(it.id + ': ' + res.why);
}
console.log('verified ' + verified + '/' + interactions.length);
for (const f of failures) console.log('FAIL ' + f);
